def encode(lat, lng, precision):
    lat_r, lng_r = [-90, 90], [-180, 180]
    bits, even = [], True
    while len(bits) < precision * 5:
        r, v = (lng_r, lng) if even else (lat_r, lat)
        mid = (r[0] + r[1]) / 2
        if v >= mid: bits.append(1); r[0] = mid
        else:        bits.append(0); r[1] = mid
        even = not even
    return base32(bits)

def cover_circle(lat, lng, radius_m):
    p = max(lv for lv in range(1, 10) if cell_min_side_m(lv) >= radius_m)
    c = encode(lat, lng, p)
    return [c] + neighbors(c)          # 9 cells

def search(lat, lng, radius_m, k):
    cands = []
    for cell in cover_circle(lat, lng, radius_m):
        cands += index.get(cell, cap=500)
    hits = [e for e in cands if haversine(lat, lng, e.lat, e.lng) <= radius_m]
    return top_k(hits, k, key=score)

def haversine(lat1, lng1, lat2, lng2):
    R = 6371000.0
    p1, p2 = radians(lat1), radians(lat2)
    dp, dl = p2 - p1, radians(lng2 - lng1)
    a = sin(dp/2)**2 + cos(p1)*cos(p2)*sin(dl/2)**2
    return 2 * R * asin(sqrt(a))

def knn(lat, lng, k, max_m=50000):
    level, seen, hits = 7, set(), []
    while level >= 3:
        for cell in cover_level(lat, lng, level):
            if cell in seen: continue
            seen.add(cell); hits += index.get(cell)
        hits.sort(key=lambda e: dist(e))
        if len(hits) >= k and dist(hits[k-1]) <= min_edge_dist(lat, lng, level):
            return hits[:k]
        level -= 1
    return [h for h in hits if dist(h) <= max_m][:k]

def score(e, req):
    d = haversine(req.lat, req.lng, e.lat, e.lng)
    dist_term = exp(-d / req.radius_m)          # 1.0 at 0 m, 0.37 at radius
    return 0.5*dist_term + 0.3*(e.rating/5) + 0.2*e.popularity + boost(e, req)
